// T1-8: nothing customer-specific is built in. The customer's name comes from GET /public/branding
// (src/lib/customer-branding.ts); this fails if "Beacon" appears (any case) in a file name or a text file under src or
// public. Tests, test fixtures and mocks may use it as data. public/sw.js is generated by the build (from src/sw).
import { existsSync, readdirSync, readFileSync, statSync } from "node:fs"
import { join, relative } from "node:path"
import { describe, expect, it } from "vitest"

const ROOT = join(__dirname, "..", "..")
const BRAND = /beacon/i
const TEXT = /\.(ts|tsx|mjs|js|cjs|css|svg|json|md|html|txt|webmanifest|xml)$/
// The one allowed line: the offline database's name, kept so tills keep their offline data (src/lib/offline/db.ts).
const ALLOWED: Record<string, string[]> = { "src/lib/offline/db.ts": ['export const OFFLINE_DB_NAME = "beacon-pos-offline"'] }

const isTestOrMock = (path: string) => /\.test\.|test-fixtures|[/\\]__mocks__[/\\]|mock/i.test(path)

function files(dir: string): string[] {
  if (!existsSync(dir)) return []
  return readdirSync(dir).flatMap((name) => {
    const path = join(dir, name)
    return statSync(path).isDirectory() ? files(path) : [relative(ROOT, path).replace(/\\/g, "/")]
  })
}

function offenders(): string[] {
  return [...files(join(ROOT, "src")), ...files(join(ROOT, "public"))]
    .filter((path) => path !== "public/sw.js" && !isTestOrMock(path))
    .flatMap((path) => {
      if (BRAND.test(path)) return [`${path} (file name)`]
      if (!TEXT.test(path)) return []
      const allowed = ALLOWED[path] ?? []
      return readFileSync(join(ROOT, path), "utf8")
        .split(/\r?\n/)
        .flatMap((line, index) => (BRAND.test(line) && !allowed.includes(line.trim()) ? [`${path}:${index + 1}`] : []))
    })
}

describe("no hard-coded brand", () => {
  it("names no business in src or public (tests and mocks excluded)", () => {
    expect(files(join(ROOT, "src"))).toContain("src/lib/brand.ts")
    expect(offenders()).toEqual([])
  })

  it("the allowed line is still there, exactly (so the exception can't grow)", () => {
    const db = readFileSync(join(ROOT, "src/lib/offline/db.ts"), "utf8")
    expect(db.split(/\r?\n/).filter((line) => BRAND.test(line) && !line.trim().startsWith("//"))).toEqual(ALLOWED["src/lib/offline/db.ts"])
  })
})
